#include "MemoryTestCoverageJson.h"
#include "MemoryTestConfigInput.h"
#include "MemoryLibraryInput.h"
#include <iostream>
#include <stdexcept>
namespace {
using namespace dft::memory;size_t checks=0;
void need(bool ok,const char *message){++checks;if(!ok)throw std::runtime_error(message);}
const MemoryTestReport &plan(const MemoryTestTimingReport &r){const auto *p=std::get_if<MemoryTestReport>(&r.source.source);return p?*p:std::get<MemoryTestRulePlan>(r.source.source).report;}
std::string json(const MemoryTestTimingReport &r){hier::protocol::JsonWriter w;writeMemoryTestTiming(w,r);return w.str();}
void totals(const MemoryTestCoverageReport &r){const auto &c=r.coverage;need(c.rows.size()==c.observedMacros&&c.timedInstances+c.blockedInstances+c.pendingInstances==c.observedMacros,"complete observed prefix accounting");need(c.complete==r.source.timeline.complete,"retain upstream completeness");for(const auto &row:c.rows){need((row.status=="timed")==row.timing.has_value(),"only published intervals");if(row.timing)need(row.timing->startPicoseconds+row.timing->durationPicoseconds==row.timing->endPicoseconds&&row.timing->endPicoseconds<=row.timing->barrierEndPicoseconds,"member interval precedes barrier");}}
}
int main()try {
 const auto dir=std::filesystem::path(DFT_MEMORY_COVERAGE_DIR);auto lib=loadMemoryLibrary(dir/"memory-test-schedule-library.json");need(bool(lib),"load library");MemoryInvestigationRequest investigation;investigation.scope="schedule_top";investigation.recursive=true;investigation.mapping.models=lib->models;
 auto loaded=loadMemoryTestConfig(dir/"memory-test-config.json",investigation,lib->testProfiles);need(bool(loaded),"load config");const auto base=*loaded;
 hier::model::OpenOptions options;options.tops={"schedule_top"};options.files={dir/"memory-test-schedule.sv"};auto design=hier::Design::open(options);need(design&&design.value()->diagnostics(100).errorCount==0,"actual RTL");auto &d=*design.value();auto result=inspectMemoryTestCoverage(d,base);need(result&&result->coverage.complete,"full coverage");totals(*result);
 const uint64_t starts[]={7,7,48014,48014,112021,112021,7,48014},durations[]={16000,16000,16000,16000,32000,32000,48000,64000},barriers[]={48007,48007,112014,112014,144021,144021,48007,112014};
 const size_t controllers[]={0,0,0,0,1,1,2,3},steps[]={0,0,1,1,0,0,0,0},waves[]={0,0,1,1,2,2,0,1};
 const auto &rows=result->coverage.rows;need(rows.size()==8&&result->coverage.timedInstances==8&&result->coverage.matchedInstances==8,"eight actual macro rows");
 for(size_t i=0;i<8;++i){const auto &r=rows[i];need(r.macro==i&&r.memory==i&&r.plannedMemory==i&&r.controller==controllers[i]&&r.step==steps[i]&&r.wave==waves[i],"handwritten original indices");need(r.status=="timed"&&r.reason.empty()&&r.timing->startPicoseconds==starts[i]&&r.timing->durationPicoseconds==durations[i]&&r.timing->barrierEndPicoseconds==barriers[i],"handwritten per-memory times include overhead, exclude barrier wait");}
 auto original=timeMemoryTests(d,base);need(original&&json(*original)==json(result->source),"original full timing report retained");
 auto request=base;request.timing.clocks.pop_back();auto r=inspectMemoryTestCoverage(d,request);need(bool(r),"missing clock report");totals(*r);need(r->coverage.timedInstances==3&&r->coverage.blockedInstances==1&&r->coverage.pendingInstances==4,"one missing-clock blocker, four pending");need(r->coverage.rows[7].reason=="clock_missing"&&r->coverage.rows[2].reason=="wave_not_committed"&&r->coverage.rows[4].reason=="timing_not_reached","failure belongs only to its entry");
 request=base;request.schedule.scheduling.policy.maxPowerMicrowatts=100000;r=inspectMemoryTestCoverage(d,request);need(bool(r),"global power report");totals(*r);need(r->coverage.blockedInstances==6&&r->coverage.timedInstances==2&&r->coverage.rows[2].reason=="prior_step_blocked"&&r->coverage.rows[0].reason=="step_power_exceeded","later step not itself classified as over power");
 request=base;request.schedule.test.investigation.mapping.limits.maxMacros=2;r=inspectMemoryTestCoverage(d,request);need(bool(r),"mapping limit report");totals(*r);need(r->coverage.observedMacros==8&&r->coverage.timedInstances==2&&r->coverage.pendingInstances==6&&!r->coverage.rows[2].memory&&r->coverage.rows[2].reason=="mapping_not_reached","known observed macros survive mapper cutoff");
 request=base;request.schedule.test.planning.limits.maxWork=2;r=inspectMemoryTestCoverage(d,request);need(bool(r),"planning limit report");totals(*r);need(r->coverage.rows[2].memory==2&&!r->coverage.rows[2].plannedMemory&&r->coverage.rows[2].reason=="planning_not_reached","no invented plan rows");
 request=base;request.schedule.test.investigation.mapping.models[0].dataBits=16;r=inspectMemoryTestCoverage(d,request);need(bool(r),"mapping mismatch report");totals(*r);need(r->coverage.blockedInstances==8&&r->coverage.rows[0].stage=="mapping"&&r->coverage.rows[0].plannedMemory==0,"earliest interface defect despite plan row");
 request=base;request.schedule.rules.reset();r=inspectMemoryTestCoverage(d,request);need(bool(r),"missing domains report");totals(*r);need(r->coverage.blockedInstances==8&&r->coverage.rows[0].reason=="domain_missing","explicit allocation required");
 request=base;request.schedule.test.planning.policy.maxPowerMicrowatts=1;r=inspectMemoryTestCoverage(d,request);need(bool(r),"local power report");totals(*r);need(r->coverage.blockedInstances==8&&r->coverage.rows[0].reason=="power_exceeded","local and global power reasons separated");
 request=base;request.schedule.scheduling.limits.maxWaves=1;r=inspectMemoryTestCoverage(d,request);need(bool(r),"schedule prefix report");totals(*r);need(r->coverage.timedInstances==3&&r->coverage.pendingInstances==5&&r->coverage.rows[2].reason=="schedule_not_reached"&&!r->coverage.rows[2].wave,"not scheduled versus not timed");
 for(auto cap:{uint64_t(1),uint64_t(48007)}){request=base;request.timing.policy.maxDurationPicoseconds=cap;r=inspectMemoryTestCoverage(d,request);need(bool(r),"duration prefix report");totals(*r);need(r->coverage.blockedInstances==0&&r->coverage.rows[cap==1?0:2].reason=="duration_limit","budget is pending, not a memory defect");}
 request=base;request.schedule.test.investigation.recursive=false;r=inspectMemoryTestCoverage(d,request);need(r&&r->coverage.complete&&r->coverage.rows.empty(),"empty complete scope");
 request=base;request.schedule.test.investigation.scope="absent";request.timing.limits.maxWork=0;r=inspectMemoryTestCoverage(d,request);need(!r&&r.error().code==hier::ErrorCode::BadRequest,"full validation before queries");request.timing.limits.maxWork=1;r=inspectMemoryTestCoverage(d,request);need(!r&&r.error().code==hier::ErrorCode::NotFound,"valid missing scope error");std::stop_source stop;stop.request_stop();request.timing.limits.maxWork=0;r=inspectMemoryTestCoverage(d,request,stop.get_token());need(!r&&r.error().code==hier::ErrorCode::Cancelled,"pre-cancel first");need(bool(inspectMemoryTestCoverage(d,base)),"recover after error");
 design.value().reset();loaded={hier::Error{hier::ErrorCode::Internal,"released"}};need(result->coverage.rows[7].timing->endPicoseconds==112014&&plan(result->source).investigation.mapping.request.models[0].words==8,"owning report after design release");hier::protocol::JsonWriter writer;writeMemoryTestCoverage(writer,*result);need(writer.str().find("rtl-memory-test-coverage-v1")!=std::string::npos,"owning serialization");
 std::cout<<checks<<" memory coverage assertions passed\n";return 0;
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}
